<?php
session_start();
require_once('check-login.php');
require_once('task-scheduler-utils.php');
task_scheduler_ensure_tables($con);
if(!(isset($_SESSION['ACCESSLEVEL'], $_SESSION['SYSTEMTYPE']) && $_SESSION['ACCESSLEVEL']==='user' && $_SESSION['SYSTEMTYPE']==='Student')){ header('location:index.php'); exit(); }
$studentId=(string)$_SESSION['USERID']; $studentEsc=mysqli_real_escape_string($con,$studentId);
if(empty($_SESSION['student_task_csrf'])){$_SESSION['student_task_csrf']=bin2hex(random_bytes(24));}
if($_SERVER['REQUEST_METHOD']==='POST' && hash_equals($_SESSION['student_task_csrf'],$_POST['csrf']??'')){
    $taskId=(int)($_POST['taskid']??0); $response=trim((string)($_POST['response']??''));
    $verify=@mysqli_query($con,"SELECT t.taskid,t.dueat FROM tblteachertask t INNER JOIN tblclass cl ON cl.class_entryid=t.classid AND cl.batchid=t.batchid AND cl.userid='$studentEsc' AND cl.status='active' WHERE t.taskid=$taskId AND t.status='published' AND t.publishat<=NOW() LIMIT 1");
    if(!$verify || !($task=mysqli_fetch_array($verify,MYSQLI_ASSOC))){$_SESSION['student_task_flash']=array('error','That task is not available to your account.');}
    elseif($response===''){$_SESSION['student_task_flash']=array('error','Write a short submission note or paste the link to your completed work.');}
    else{$status=strtotime($task['dueat'])<time()?'late':'submitted';$stmt=mysqli_prepare($con,'INSERT INTO tblteachertasksubmission(taskid,studentid,response,status,submittedat) VALUES(?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE response=VALUES(response),status=VALUES(status),submittedat=NOW()');mysqli_stmt_bind_param($stmt,'isss',$taskId,$studentId,$response,$status);$ok=mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);$_SESSION['student_task_flash']=$ok?array('success',$status==='late'?'Work submitted late. Your teacher can see the submission time.':'Work submitted on time. Great job!'):array('error','Your work could not be submitted. Please try again.');}
    header('location:student-tasks.php');exit();
}
$flash=$_SESSION['student_task_flash']??'';unset($_SESSION['student_task_flash']);
$tasks=array();$taskSql="SELECT DISTINCT t.*,ce.class_name,bh.batch,sub.subject,CONCAT(TRIM(COALESCE(u.firstname,'')),' ',TRIM(COALESCE(u.surname,''))) teacher_name,s.response,s.submittedat,s.status AS submission_status
FROM tblteachertask t INNER JOIN tblclass cl ON cl.class_entryid=t.classid AND cl.batchid=t.batchid AND cl.userid='$studentEsc' AND cl.status='active'
INNER JOIN tblclassentry ce ON ce.class_entryid=t.classid LEFT JOIN tblbatch bh ON bh.batchid=t.batchid INNER JOIN tblsubjectclassification sc ON sc.classificationid=t.classificationid INNER JOIN tblsubject sub ON sub.subjectid=sc.subjectid LEFT JOIN tblsystemuser u ON u.userid=t.teacherid LEFT JOIN tblteachertasksubmission s ON s.taskid=t.taskid AND s.studentid='$studentEsc'
WHERE t.status IN ('published','closed') AND t.publishat<=NOW() ORDER BY (s.submissionid IS NULL AND t.status='published') DESC,t.dueat ASC,t.createdat DESC LIMIT 100";
$taskRes=@mysqli_query($con,$taskSql);if($taskRes){while($row=mysqli_fetch_array($taskRes,MYSQLI_ASSOC)){$tasks[]=$row;}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Tasks</title><?php include('links.php'); ?><link rel="stylesheet" href="css/task-scheduler.css"></head><body class="task-page task-page--student"><main class="task-shell"><a class="task-back" href="student-page.php"><i class="fa fa-arrow-left"></i> Student dashboard</a><section class="task-hero"><div><span>My learning planner</span><h1>My Tasks</h1><p>See exactly what is due, plan your time, and submit your work in one focused place.</p></div><i class="fa fa-rocket"></i></section><?php if($flash){ ?><div class="task-flash task-flash--<?php echo task_scheduler_escape($flash[0]); ?>"><?php echo task_scheduler_escape($flash[1]); ?></div><?php } ?><section class="task-list"><div class="task-section-heading"><div><span>Your deadlines</span><h2>Keep moving forward</h2></div><p><?php echo count($tasks); ?> visible task<?php echo count($tasks)===1?'':'s'; ?></p></div><?php if(count($tasks)>0){ ?><div class="task-grid"><?php foreach($tasks as $task){$overdue=strtotime($task['dueat'])<time()&&empty($task['submissionid']);$submitted=!empty($task['submissionid']);?><article class="task-card <?php echo $overdue?'task-card--overdue':''; ?>"><div class="task-card__top"><span class="task-pill"><?php echo task_scheduler_escape($task['tasktype']); ?></span><?php if($submitted){ ?><span class="task-state task-state--submitted"><i class="fa fa-check"></i> <?php echo $task['submission_status']==='late'?'Submitted late':'Submitted'; ?></span><?php }elseif($task['status']==='closed'){ ?><span class="task-state task-state--closed">Closed</span><?php }elseif($overdue){ ?><span class="task-state task-state--overdue">Overdue</span><?php }else{ ?><span class="task-state task-state--published">To do</span><?php } ?></div><h3><?php echo task_scheduler_escape($task['title']); ?></h3><p class="task-card__context"><?php echo task_scheduler_escape($task['subject'].' · '.$task['class_name']); ?></p><p class="task-card__teacher">Set by <?php echo task_scheduler_escape(trim($task['teacher_name'])?:'Your teacher'); ?></p><?php if(trim($task['instructions'])!==''){ ?><p class="task-card__instructions"><?php echo nl2br(task_scheduler_escape($task['instructions'])); ?></p><?php } ?><div class="task-deadline"><i class="fa fa-clock-o"></i><div><span><?php echo $overdue?'Was due':'Due'; ?></span><strong><?php echo task_scheduler_escape(task_scheduler_due_label($task['dueat'])); ?></strong></div></div><?php if($submitted){ ?><div class="task-submitted-note"><i class="fa fa-check-circle"></i><span>Submitted <?php echo task_scheduler_escape(task_scheduler_due_label($task['submittedat'])); ?></span></div><?php }elseif($task['status']==='published'){ ?><form method="post" class="task-submit"><input type="hidden" name="csrf" value="<?php echo task_scheduler_escape($_SESSION['student_task_csrf']); ?>"><input type="hidden" name="taskid" value="<?php echo (int)$task['taskid']; ?>"><label>Submit your work<textarea name="response" required placeholder="Write your answer, a short note, or paste a link to your work."></textarea></label><button class="task-primary" type="submit"><i class="fa fa-upload"></i> Submit work</button></form><?php } ?></article><?php } ?></div><?php }else{ ?><div class="task-empty"><i class="fa fa-smile-o"></i><strong>No tasks yet</strong><p>When one of your teachers schedules work for your class, it will appear here.</p></div><?php } ?></section></main></body></html>
